  // 生成三数组比较题目的辅助函数
  const generateThreeNumberComparisonProblem = (operationType) => {
    // 生成三个随机数用于比较
    let num1 = Math.floor(Math.random() * (maxNumber - minNumber + 1)) + minNumber;
    let num2 = Math.floor(Math.random() * (maxNumber - minNumber + 1)) + minNumber;
    let num3 = Math.floor(Math.random() * (maxNumber - minNumber + 1)) + minNumber;
    
    // 确保除法中不包含0
    if (operationType === 'division') {
      num1 = Math.max(1, num1);
      num2 = Math.max(1, num2);
      num3 = Math.max(1, num3);
    }
    
    // 随机决定是左边2个数运算还是右边2个数运算
    const useLeftOperation = Math.random() > 0.5;
    
    let leftResult, rightResult;
    let problem, answer, min_answer, max_answer;
    
    switch(operationType) {
      case 'addition':
        if (useLeftOperation) {
          // 左边两个数相加，右边一个数
          leftResult = num1 + num2;
          rightResult = num3;
          problem = `${num1} + ${num2} ◯ ${num3}`;
          min_answer = leftResult;
          max_answer = leftResult;
        } else {
          // 左边一个数，右边两个数相加
          leftResult = num3;
          rightResult = num1 + num2;
          problem = `${num3} ◯ ${num1} + ${num2}`;
          min_answer = rightResult;
          max_answer = rightResult;
        }
        break;
        
      case 'subtraction':
        if (useLeftOperation) {
          // 左边两个数相减，右边一个数
          if (allowNegative || num1 >= num2) {
            leftResult = num1 - num2;
            rightResult = num3;
            problem = `${num1} - ${num2} ◯ ${num3}`;
          } else {
            leftResult = num2 - num1;
            rightResult = num3;
            problem = `${num2} - ${num1} ◯ ${num3}`;
          }
          min_answer = leftResult;
          max_answer = leftResult;
        } else {
          // 左边一个数，右边两个数相减
          leftResult = num3;
          if (allowNegative || num1 >= num2) {
            rightResult = num1 - num2;
            problem = `${num3} ◯ ${num1} - ${num2}`;
          } else {
            rightResult = num2 - num1;
            problem = `${num3} ◯ ${num2} - ${num1}`;
          }
          min_answer = rightResult;
          max_answer = rightResult;
        }
        break;
        
      case 'multiplication':
        if (useLeftOperation) {
          // 左边两个数相乘，右边一个数
          leftResult = num1 * num2;
          rightResult = num3;
          problem = `${num1} × ${num2} ◯ ${num3}`;
          min_answer = leftResult;
          max_answer = leftResult;
        } else {
          // 左边一个数，右边两个数相乘
          leftResult = num3;
          rightResult = num1 * num2;
          problem = `${num3} ◯ ${num1} × ${num2}`;
          min_answer = rightResult;
          max_answer = rightResult;
        }
        break;
        
      case 'division':
        // 确保除法可以整除
        const divisor = Math.max(1, num2);
        const dividend = divisor * num1;  // 确保可以整除
        num3 = Math.max(1, num3); // 确保比较数不为0
        
        if (useLeftOperation) {
          // 左边两个数相除，右边一个数
          leftResult = dividend / divisor;
          rightResult = num3;
          problem = `${dividend} ÷ ${divisor} ◯ ${num3}`;
        } else {
          // 左边一个数，右边两个数相除
          leftResult = num3;
          rightResult = dividend / divisor;
          problem = `${num3} ◯ ${dividend} ÷ ${divisor}`;
        }
        min_answer = dividend;
        max_answer = dividend;
        break;
        
      default:
        // 默认使用加法
        if (useLeftOperation) {
          leftResult = num1 + num2;
          rightResult = num3;
          problem = `${num1} + ${num2} ◯ ${num3}`;
        } else {
          leftResult = num3;
          rightResult = num1 + num2;
          problem = `${num3} ◯ ${num1} + ${num2}`;
        }
        min_answer = num1 + num2;
        max_answer = num1 + num2;
    }
    
    // 比较结果
    if (leftResult === rightResult) {
      answer = '=';
    } else if (leftResult > rightResult) {
      answer = '>';
    } else {
      answer = '<';
    }

    return { problem, answer, min_answer, max_answer };
  };

